use ranked_game::{
    ACTIONS_PER_SEGMENT, MAX_SEGMENTS, Action, GameState, Rng, new_game,
    replay_action, state_commitment,
};

fn main(
    seed: pub Field,
    player: pub Field,
    stance_id: pub u8,
    final_score: pub u32,
    segment_index: pub u8,
    previous_commitment: pub Field,
    next_commitment: pub Field,
    is_final: pub bool,
    previous_state: GameState,
    previous_rng: u32,
    previous_salt: Field,
    next_salt: Field,
    actions: [Action; ACTIONS_PER_SEGMENT],
) {
    assert(player != 0);
    assert(stance_id < 3);
    assert((segment_index as u32) < MAX_SEGMENTS);

    let (mut state, mut rng) = if segment_index == 0 {
        assert(previous_commitment == 0);
        new_game(seed, stance_id)
    } else {
        assert(previous_commitment != 0);
        assert(previous_state.stance == stance_id);
        assert(!previous_state.victory & !previous_state.failed);
        assert(state_commitment(&previous_state, previous_rng, previous_salt) == previous_commitment);
        (previous_state, Rng { value: previous_rng })
    };

    for i in 0..ACTIONS_PER_SEGMENT {
        replay_action(&mut state, &mut rng, actions[i]);
    }

    assert(!state.failed, "Run lost the game");
    if is_final {
        assert(state.victory, "Run did not end in victory");
        assert(state.cash == final_score);
        assert(next_commitment == 0);
    } else {
        assert(!state.victory);
        assert(next_commitment != 0);
        assert(state_commitment(&state, rng.value, next_salt) == next_commitment);
    }
}

