// =============================================================================
// Constants & Limits (Compile-Time Fixed for ZK)
// =============================================================================
pub global MAX_ACTIONS: u32 = 96;
global MAX_ENEMY_CARDS_PER_TURN: u32 = 6;
global MIN_ENEMY_CARDS: u8 = 2;
global BOARD_MAJORITY: u8 = 5;

// Action opcodes
pub global OP_NOOP: u8 = 0;
pub global OP_PLAY_CARD: u8 = 1;
pub global OP_USE_JACKET: u8 = 2;
pub global OP_USE_EQUITY: u8 = 3;
pub global OP_USE_RALLY: u8 = 4;
pub global OP_MULLIGAN: u8 = 5;
pub global OP_END_TURN: u8 = 6;

// Seat owners
pub global OWNER_NEUTRAL: u8 = 0;
pub global OWNER_PLAYER: u8 = 1;
pub global OWNER_ENEMY: u8 = 2;

// Card categories
global CAT_STAMINA: u8 = 0;
global CAT_INFLUENCE: u8 = 1;
global CAT_SPY: u8 = 2;
global CAT_POLITICS: u8 = 3;

// Affix encoding (0 = none, 1..9 = positive by stance, 10..18 = negative)
global AFFIX_NONE: u8 = 0;

// Boss IDs (0..10 matching AI_BOSS_POOL order in ai.js)
global BOSS_ELENA: u8 = 0;
global BOSS_COLE: u8 = 1;
global BOSS_MARCUS: u8 = 2;
global BOSS_VICTOR: u8 = 3;
global BOSS_DR_K: u8 = 4;
global BOSS_LEO: u8 = 5;
global BOSS_ARTHUR: u8 = 6;
global BOSS_SOPHIA: u8 = 7;
global BOSS_MILLER: u8 = 8;
global BOSS_BARON: u8 = 9;
global BOSS_REX: u8 = 10;

pub struct Action {
    pub op: u8,
    pub arg: u8,
}

pub struct Rng {
    pub value: u32,
}

impl Rng {
    // Mirror seededRandom in game-rules.mjs, including its 32-bit wrapping.
    pub fn next(&mut self) -> u32 {
        self.value = ((self.value as u64) + 0x6D2B79F5) as u32;
        let value = self.value;
        let mut mixed = (((value ^ (value >> 15)) as u64) * ((value | 1) as u64)) as u32;
        let secondary = ((mixed as u64) + ((mixed ^ (mixed >> 7)) as u64) * ((mixed | 61) as u64)) as u32;
        mixed = mixed ^ secondary;
        mixed ^ (mixed >> 14)
    }

    fn next_u32(&mut self, bound: u32) -> u32 {
        (((self.next() as u64) * (bound as u64)) >> 32) as u32
    }
}

pub struct GameState {
    stage: u8,              // 1..3
    turn: u8,               // 1..6
    boss_ids: [u8; 3],
    pub stance: u8,             // 0=geek, 1=capital, 2=iron
    ap: u8,
    max_ap: u8,
    pub cash: u32,
    pub influence: u8,
    jacket_uses: u8,
    equity_uses: u8,
    pub rally_uses: u8,
    powers_used: [bool; 3],
    mulligan_used: bool,
    hero_passive_used: bool,
    ai_frozen: bool,
    ai_penalty: u8,
    cards_played_turn: u8,
    pub seats_owner: [u8; 9],
    pub seats_locked: [bool; 9],
    deck: [u8; 21],
    deck_len: u8,
    discard: [u8; 21],
    discard_len: u8,
    hand_key: [u8; 5],
    hand_affix: [u8; 5],
    hand_len: u8,
    pub victory: bool,
    pub failed: bool,
}

struct CardDef {
    category: u8,
    ap_cost: u8,
    cash_cost: u32,
    inf_cost: u8,
    gain_ap: u8,
    gain_cash: u32,
    gain_inf: u8,
    draw: u8,
    claim_neutral: u8,
    claim_any: u8,
    steal_enemy: u8,
    steal_or_claim: u8,
    demote_enemy: u8,
    lock_claimed: bool,
    weaken_ai: u8,
    freeze_ai: bool,
}

fn get_card(key: u8) -> CardDef {
    if key == 0 {
        // chimaek
        CardDef { category: CAT_STAMINA, ap_cost: 0, cash_cost: 100, inf_cost: 0, gain_ap: 2, gain_cash: 0, gain_inf: 0, draw: 0, claim_neutral: 0, claim_any: 0, steal_enemy: 0, steal_or_claim: 0, demote_enemy: 0, lock_claimed: false, weaken_ai: 0, freeze_ai: false }
    } else if key == 1 {
        // coffee
        CardDef { category: CAT_STAMINA, ap_cost: 0, cash_cost: 0, inf_cost: 0, gain_ap: 1, gain_cash: 0, gain_inf: 0, draw: 1, claim_neutral: 0, claim_any: 0, steal_enemy: 0, steal_or_claim: 0, demote_enemy: 0, lock_claimed: false, weaken_ai: 0, freeze_ai: false }
    } else if key == 2 {
        // nightmarket
        CardDef { category: CAT_STAMINA, ap_cost: 1, cash_cost: 100, inf_cost: 0, gain_ap: 1, gain_cash: 500, gain_inf: 5, draw: 0, claim_neutral: 0, claim_any: 0, steal_enemy: 0, steal_or_claim: 0, demote_enemy: 0, lock_claimed: false, weaken_ai: 0, freeze_ai: false }
    } else if key == 3 {
        // banquet
        CardDef { category: CAT_STAMINA, ap_cost: 2, cash_cost: 300, inf_cost: 0, gain_ap: 0, gain_cash: 1400, gain_inf: 10, draw: 0, claim_neutral: 0, claim_any: 0, steal_enemy: 0, steal_or_claim: 0, demote_enemy: 0, lock_claimed: false, weaken_ai: 0, freeze_ai: false }
    } else if key == 4 {
        // pr_troll
        CardDef { category: CAT_INFLUENCE, ap_cost: 1, cash_cost: 400, inf_cost: 0, gain_ap: 0, gain_cash: 0, gain_inf: 12, draw: 0, claim_neutral: 1, claim_any: 0, steal_enemy: 0, steal_or_claim: 0, demote_enemy: 0, lock_claimed: false, weaken_ai: 0, freeze_ai: false }
    } else if key == 5 {
        // inf_livestream
        CardDef { category: CAT_INFLUENCE, ap_cost: 1, cash_cost: 200, inf_cost: 0, gain_ap: 0, gain_cash: 0, gain_inf: 15, draw: 1, claim_neutral: 0, claim_any: 0, steal_enemy: 0, steal_or_claim: 0, demote_enemy: 0, lock_claimed: false, weaken_ai: 0, freeze_ai: false }
